head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.selfID = ""; // ID를 opener가 넘기는 값을 받는 변수형태로 사용하기 위함.
scwin.gJongcode = ""; // 업종코드
scwin.ssMarket = "N"; // 종목콤보확인
scwin.stat = "";
scwin.gListStatCd = "";
scwin.skw = "";
// var tpcd = frame.Provider("../").js_com_market;//세션의 시장구분
scwin.tpcd = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.stat = $c.frame.path("../").js_listStatCd;
        // 상장상태여부

        if (scwin.stat === undefined) {
            scwin.stat = "";
        } else {
            scwin.gListStatCd = scwin.stat;
            if (scwin.gListStatCd === "Y") {
                combo_stat.bindColVal = 'Y';
                combo_stat.setDisabled(true);
            }
        }
        $c.cm.PanelToGroupBox_01(panel_1);
        $c.cm.PanelToGroupBox_02(panel_2);
        scwin.resizeToWin();
        const sbmOptions = {
            id : "sbm_dts_jongmok",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_jongmok=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_MxDataSet_code1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code1=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions3 = {
            id : "sbm_MxDataSet_code2",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_code2=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.code1Sync();
        await scwin.listSync();
        scwin.selfID = frame.FrameID; // ID 할당.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_jongmok_OnLoadCompleted
 * @description dts_jongmok 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name MxDataSet_code1_OnLoadCompleted
 * @description MxDataSet_code1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxDataSet_code1_OnLoadCompleted = async function(rowcount) {
    try {
        await scwin.marketSetCombo();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.MxDataSet_code1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxDataSet_code1_OnFilter
 * @description Mx Data Set code1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_code1_OnFilter = function(row) {
    try {
        if (dts_jongmok.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD") === scwin.gJongcode) return true;

        else return false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_POP.MxDataSet_code1_OnFilter" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnKeyPress
 * @description grd jongmok On Key Press 처리
 * @param {*} kcode kcode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnKeyPress = async function(kcode) {
    try {
        if (kcode === '13') {
            // Confirm();
            await scwin.setAdm_Itm(grd_jongmok, row, colid);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.grd_jongmok_OnKeyPress" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnDblClick
 * @description grd_jongmok 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnDblClick = async function(row, colid) {
    try {
        // Confirm();
        await scwin.setAdm_Itm(grd_jongmok, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.grd_jongmok_OnDblClick" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_search_onclick = function() {
    try {
        scwin.JongmokName(txb_jongmokName.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_POP.img_search_onclick" });
    }
};

/**
 * @method
 * @name txb_jongmokName_onkeydown
 * @description txb_jongmokName 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_jongmokName_onkeydown = function() {
    try {
        if (window.event.keyCode === "13") {
            // JongmokName(window.event.keyCode);
            $c.stockSearch.JongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_POP.txb_jongmokName_onkeydown" });
    }
};

/**
 * @method
 * @name combo_market_onselchange
 * @description combo_market onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.combo_market_onselchange = async function() {
    try {
        if (scwin.ssMarket === "Y") {
            txb_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = MxDataSet_code1.getCellData(combo_market.getSelectedIndex() + 1, "CD_VAL");
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.combo_market_onselchange" });
    }
};

/**
 * @method
 * @name combo_stat_onselchange
 * @description combo_stat onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.combo_stat_onselchange = async function() {
    try {
        txb_jongmokName.setValue("");
        scwin.skw = "";
        scwin.stat = $c.cp.valueOfIndex(combo_stat, "Column2", combo_stat.getSelectedIndex());
        if (scwin.stat === '0') {
            scwin.stat = "";
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007_POP.combo_stat_onselchange" });
    }
};

/**
 * @method
 * @name dts_jongmok_OnFilter
 * @description jongmok On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnFilter = function(row) {
    try {
        if (scwin.skw !== "") {
            f1 = (dts_jongmok.getCellData(row, "COM_ABBRV")).toUpperCase();
            f2 = (dts_jongmok.getCellData(row, "OLD_COM_ABBRV")).toUpperCase();
            f3 = (dts_jongmok.getCellData(row, "COM_NM")).toUpperCase();
            if (f1.indexOf(scwin.skw) !== -1) {
                return true;
            } else if (f2.indexOf(scwin.skw) !== -1) {
                return true;
            } else if (f3.indexOf(scwin.skw) !== -1) {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_POP.dts_jongmok_OnFilter" });
    }
};

