    // MoveCenterOfParent();

};

/**
 * @method
 * @name Jongmok
 * @description 가나다라..검색
 * @param {*} prevval prevval
 * @param {*} nextval nextval
 * @returns {void}
 * @hidden N
 */
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    // dts_jongmok.sort(); // W-Craft 주석처리
    let cnt = 0;
    for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
    grd_jongmok.focus();
};

/**
 * @method
 * @name JongmokName
 * @description 종목명검색
 * @param {*} keyCode keyCode
 * @returns {void}
 * @hidden N
 */
scwin.JongmokName = function(keyCode) {
    // if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    // dts_jongmok.sort(); // W-Craft 주석처리
    let cnt = 0;
    const len = txb_jongmokName.getValue().length;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal === name) {
            cnt = i;
            break;
        }
    }
    if (cnt === 0) {
        dts_jongmok.sort("+COM_NM", 0);
        // dts_jongmok.sort(); // W-Craft 주석처리
        for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
            let name = dts_jongmok.getCellData(i, "COM_NM").substring(0, len).toUpperCase();
            if (txtVal === name) {
                cnt = i;
                break;
            }
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
};

/**
 * @method
 * @name JongmokSearch
 * @description 종목명검색
 * @returns {void}
 * @hidden N
 */
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    dts_jongmok.setRowPosition(1, 0);
};

/**
 * @method
 * @name setAdm_Itm
 * @description 부모창으로 종목코드 전달
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAdm_Itm = async function(GridID, row, ColID) {
    await scwin.setAdm_Itm_For_Grid(GridID, row, ColID);
};

/**
 * @method
 * @name setAdm_Itm_For_Grid
 * @description set Adm Itm For Grid 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAdm_Itm_For_Grid = async function(GridID, row, ColID) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    const parentWin = $c.frame.path("../");
    parentWin.dts_RepcReqPrn.setCellData(parentWin.dts_RepcReqPrn.getFocusedRowIndex(), "ISUR_CD", objDataID.getCellData(row, "ISUR_CD"));
    parentWin.dts_RepcReqPrn.setCellData(parentWin.dts_RepcReqPrn.getFocusedRowIndex(), "COM_ABBRV", objDataID.getCellData(row, "COM_ABBRV"));
    parentWin.dts_RepcReqPrn.setCellData(parentWin.dts_RepcReqPrn.getFocusedRowIndex(), "LD_MKT_TP_CD", objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD"));
    await $c.win.closePopup();
};

/**
 * @method
 * @name marketSetCombo
 * @description market Set Combo 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.marketSetCombo = async function() {
    let cIndex;
    let name;
    if (scwin.tpcd !== "") {
        for (i = 1; i <= MxDataSet_code1.getRowCount(); i++) {
            name = MxDataSet_code1.getCellData(i, "CD_VAL");
            if (name === scwin.tpcd) {
                cIndex = i - 1;
                break;
            }
        }
        // 사용자의 시장구분값이 없을 시 '조건없음' 으로 초기화
        if (scwin.tpcd !== "1" && scwin.tpcd !== "2" && scwin.tpcd !== "6") {
            combo_market.setSelectedIndex(0);
            txb_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = MxDataSet_code1.getCellData(combo_market.getSelectedIndex() + 1, "CD_VAL");
            await scwin.listSync();
        } else {
            combo_market.setSelectedIndex(cIndex);
        }
    }
    if (scwin.tpcd === "1" || scwin.tpcd === "2" || scwin.tpcd === "6") {
        combo_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};
